'use strict';
const videoMedia=new Map();let videoImportBusy=false;
document.querySelector('.tabs').insertAdjacentHTML('afterbegin','<button data-tab="media">Media</button>');
$('sceneTab').insertAdjacentHTML('beforebegin',`<div id="mediaTab" hidden><p class="note">VIDEO & IMAGES</p><h3>Bring your footage into the story.</h3><label class="button media-import">＋ Import video<input id="videoFile" type="file" accept="video/mp4,video/webm,video/quicktime,video/ogg" multiple hidden></label><label><input id="extractVideoAudio" type="checkbox" checked> Include original audio</label><p class="note">MP4 or WebM · up to 80 MB per clip. Unsupported codecs need conversion first.</p><div id="mediaLibrary" class="media-library"></div><button id="importImageMedia">＋ Import image</button></div>`);
const tabsBeforeMedia=tab;tab=function(name){tabsBeforeMedia(name);$('mediaTab').hidden=name!=='media'};document.querySelector('[data-tab="media"]').onclick=()=>tab('media');$('importImageMedia').onclick=()=>$('imageFile').click();
function mediaReady(video,event='loadeddata'){return new Promise((resolve,reject)=>{if(event==='loadeddata'&&video.readyState>=2||event==='loadedmetadata'&&video.readyState>=1)return resolve(video);const timer=setTimeout(()=>finish(Error('This video did not load. Try an H.264 MP4 or a VP9 WebM.')),20000);const ok=()=>finish(),bad=()=>finish(Error('This video codec is not supported.'));function finish(error){clearTimeout(timer);video.removeEventListener(event,ok);video.removeEventListener('error',bad);error?reject(error):resolve(video)}video.addEventListener(event,ok,{once:true});video.addEventListener('error',bad,{once:true})})}
function videoFor(o){let entry=videoMedia.get(o.id);if(entry&&entry.src===o.src)return entry.video;if(entry){entry.video.pause();entry.video.removeAttribute('src');entry.video.load()}const video=document.createElement('video');video.muted=true;video.preload='auto';video.playsInline=true;video.src=o.src;video.onseeked=()=>{if(!playing&&!recording)draw()};video.onloadeddata=()=>{if(!playing&&!recording)draw()};videoMedia.set(o.id,{src:o.src,video});return video}
function pauseVideoMedia(){for(const entry of videoMedia.values())entry.video.pause()}
function syncVideoMedia(){const active=new Set();for(const o of current().objects.filter(o=>o.type==='video')){const video=videoFor(o);if(!visibleAt(o,time)||video.readyState<2){video.pause();continue}active.add(o.id);const desired=clamp(o.sourceOffset+time-clipStart(o),0,Math.max(0,o.sourceDuration-.001));if(!video.seeking&&Math.abs(video.currentTime-desired)>((playing||recording)&&!video.paused?.15:.015))video.currentTime=desired;if((playing||recording)&&desired<o.sourceDuration-.02){if(video.paused&&!video.seeking)video.play().catch(()=>{})}else video.pause()}for(const [id,entry] of videoMedia)if(!active.has(id))entry.video.pause()}
function drawVideoObject(c,o,v){const video=videoFor(o);if(video.readyState<2)return;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity;c.drawImage(video,-o.width/2,-o.height/2,o.width,o.height);c.restore()}
async function seekVideo(video,t){await mediaReady(video);if(Math.abs(video.currentTime-t)<.01&&!video.seeking)return;const done=mediaReady(video,'seeked');video.currentTime=t;await done}
async function prepareVideoExport(){for(const s of project.scenes)for(const o of s.objects.filter(o=>o.type==='video')){const video=videoFor(o);video.pause();await seekVideo(video,o.sourceOffset)}}
function syncLinkedAudio(o){for(const c of tracks().filter(c=>c.videoId===o.id)){c.start=sceneOffset()+clipStart(o);c.offset=o.sourceOffset;c.duration=clipEnd(o)-clipStart(o);const fade=fadeDurations(c);c.fadeIn=fade.in;c.fadeOut=fade.out}}
function normalizeLinkedMedia(){const clips=new Map();let offset=0;for(const s of project.scenes){for(const o of s.objects)if(o.type==='video')clips.set(o.id,{o,s,offset});offset+=s.duration}project.audioClips=tracks().filter(c=>!c.videoId||clips.has(c.videoId));for(const c of tracks()){if(!c.videoId)continue;const {o,s,offset}=clips.get(c.videoId);c.start=offset+clipStart(o);c.offset=o.sourceOffset;c.duration=Math.min(clipEnd(o,s)-clipStart(o),c.sourceDuration-c.offset);const f=fadeDurations(c);c.fadeIn=f.in;c.fadeOut=f.out}}
function duplicateLinkedAudio(original,copy){for(const c of tracks().filter(c=>c.videoId===original.id)){const clone={...c,id:uid(),videoId:copy.id};tracks().push(clone);audioBuffers.set(clone.id,audioBuffers.get(c.id))}}
const saveBeforeMedia=save;save=function(){normalizeLinkedMedia();saveBeforeMedia()};
const visualMoveBeforeVideo=moveVisual;moveVisual=function(o,change){if(o.locked)return;if(o.type!=='video')return visualMoveBeforeVideo(o,change);const start=clipStart(o),end=clipEnd(o);if(change.mode==='left'){const next=clamp(start+change.delta,Math.max(0,start-o.sourceOffset),end-.1);o.sourceOffset+=next-start;o.in=next}else if(change.mode==='right')o.out=clamp(end+change.delta,start+.1,Math.min(current().duration,start+o.sourceDuration-o.sourceOffset));else visualMoveBeforeVideo(o,change);syncLinkedAudio(o)};
const audioMoveBeforeVideo=moveAudio;moveAudio=function(c,change){if(change.mode==='move'||change.mode==='left'||change.mode==='right')delete c.videoId;audioMoveBeforeVideo(c,change)};
async function importVideoFiles(files){if(recording||videoImportBusy)return;stop();videoImportBusy=true;const generation=project;try{for(const file of files){if(file.size>80e6){toast('Choose a video smaller than 80 MB.');continue}const src=await dataURL(file),probe=document.createElement('video');probe.muted=true;probe.preload='auto';probe.src=src;await mediaReady(probe);if(!Number.isFinite(probe.duration)||probe.duration<.1)throw Error('This video has no usable duration.');if(project!==generation)throw Error('The project changed during import. Import again.');const start=Math.min(time,current().duration-.1),duration=Math.min(probe.duration,current().duration-start),width=800,height=width*probe.videoHeight/probe.videoWidth,f=Math.min(1,450/height);const o=newObject('video',{name:file.name,src,sourceDuration:probe.duration,sourceOffset:0,width:width*f,height:height*f,in:start,out:start+duration});o.keys=[{t:start,v:{...pose,x:480,y:270}}];videoMedia.set(o.id,{src,video:probe});probe.onseeked=()=>{if(!playing&&!recording)draw()};
 if($('extractVideoAudio').checked){try{const buffer=await decodeFile(file),c={id:uid(),name:file.name+' · original audio',role:'effect',start:sceneOffset()+start,offset:0,duration:Math.min(duration,buffer.duration),sourceDuration:buffer.duration,volume:1,src,videoId:o.id};tracks().push(c);audioBuffers.set(c.id,buffer)}catch{toast('Video imported. No decodable audio track was found.')}}selected=o.id;selectedAudio=null;save();render();toast('Video added. Drag the clip edges to trim; animate layers over it.')}}catch(e){toast(e.message||'Video could not be imported.')}finally{videoImportBusy=false}}
$('videoFile').onchange=e=>{const files=[...e.target.files];e.target.value='';importVideoFiles(files)};
function renderMediaLibrary(){const el=$('mediaLibrary');el.replaceChildren();const objects=project.scenes.flatMap(s=>s.objects.filter(o=>o.type==='video').map(o=>({o,s})));if(!objects.length){el.innerHTML='<p class="note">Imported footage appears here and on its own timeline track.</p>';return}for(const {o,s} of objects){const b=document.createElement('button');b.className='media-item';b.textContent='▶ '+o.name;const sub=document.createElement('small');sub.textContent=s.name+' · '+o.sourceDuration.toFixed(1)+'s';b.append(sub);b.onclick=()=>{stop();sceneIndex=project.scenes.indexOf(s);time=clipStart(o);selected=o.id;selectedAudio=null;render()};el.append(b)}}
const drawBeforeVideo=draw;draw=function(){syncVideoMedia();drawBeforeVideo()};const stopBeforeVideo=stop;stop=function(){stopBeforeVideo();pauseVideoMedia()};
const renderBeforeVideo=render;render=function(){renderBeforeVideo();renderMediaLibrary();const active=new Set(project.scenes.flatMap(s=>s.objects.filter(o=>o.type==='video').map(o=>o.id)));for(const [id,entry] of videoMedia)if(!active.has(id)){entry.video.pause();entry.video.removeAttribute('src');entry.video.load();videoMedia.delete(id)}};
const controlsBeforeVideo=renderControls;renderControls=function(){controlsBeforeVideo();const o=object();if(!o)return;const section=document.createElement('div');section.className='clip-effects';section.innerHTML='<h3>Clip effects</h3><label>Look<select id="clipLook"><option value="none">Original</option><option value="warm">Warm paper</option><option value="mono">Black & white</option><option value="vivid">Vivid</option><option value="soft">Soft</option></select></label><label>Fade in<input id="visualFadeIn" type="number" min="0" step="0.1" value="0"></label><label>Fade out<input id="visualFadeOut" type="number" min="0" step="0.1" value="0"></label>';
 if(o.type==='video')section.insertAdjacentHTML('beforeend','<p class="note">Footage is muted in the player. Original audio plays from its linked timeline track.</p><label>Source trim<input id="videoSource" type="number" min="0" step="0.1"></label><button id="fitVideo">Fit frame</button> <button id="fillVideo">Fill frame</button>');$('controls').append(section);$('clipLook').value=o.look||'none';$('clipLook').onchange=e=>{o.look=e.target.value;save();draw()};for(const [id,key] of [['visualFadeIn','fadeIn'],['visualFadeOut','fadeOut']]){$(id).value=o[key]||0;$(id).max=clipEnd(o)-clipStart(o);$(id).onchange=e=>{o[key]=clamp(+e.target.value||0,0,clipEnd(o)-clipStart(o));save();draw()}}if(o.type==='video'){$('videoSource').value=o.sourceOffset;$('videoSource').max=o.sourceDuration-(clipEnd(o)-clipStart(o));$('videoSource').onchange=e=>{o.sourceOffset=clamp(+e.target.value||0,0,Math.max(0,o.sourceDuration-(clipEnd(o)-clipStart(o))));syncLinkedAudio(o);save();draw()};for(const [id,fit] of [['fitVideo',Math.min],['fillVideo',Math.max]])$(id).onclick=()=>{const scale=fit(960/o.width,540/o.height);setKey(o,{...stateAt(o,time),x:480,y:270,scale});render()}}section.querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o.locked)};
function applyVisualEffects(c,o,v,t){const span=clipEnd(o)-clipStart(o),a=Math.min(o.fadeIn||0,span),b=Math.min(o.fadeOut||0,span);v.opacity*=clamp(Math.min(a?(t-clipStart(o))/a:1,b?(clipEnd(o)-t)/b:1),0,1);c.filter=({warm:'sepia(.25) saturate(1.1)',mono:'grayscale(1)',vivid:'saturate(1.5) contrast(1.08)',soft:'saturate(.8) contrast(.9) brightness(1.08)'})[o.look]||'none'}
const validBeforeVideo=valid;valid=function(p){return validBeforeVideo(p)&&p.scenes.every(s=>(s.transitionDuration===undefined||Number.isFinite(s.transitionDuration)&&s.transitionDuration>=.1&&s.transitionDuration<=3)&&s.objects.every(o=>(!o.look||['none','warm','mono','vivid','soft'].includes(o.look))&&['fadeIn','fadeOut'].every(k=>o[k]===undefined||Number.isFinite(o[k])&&o[k]>=0&&o[k]<=s.duration)&&(o.type!=='video'||o.sourceOffset+((o.out??s.duration)-(o.in??0))*(o.speed||1)<=o.sourceDuration+.05)))};
const exportBeforeMedia=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{if(videoImportBusy)return toast('Wait for video import to finish.');return exportBeforeMedia()};
